import{_ as s,o as n,c as t,a2 as a}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":1793100380000}'),o={name:"guide/agents.md"};function l(c,e,p,d,r,i){return n(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><p>An agent is a typed config object passed to <code>defineAgent()</code>. It names a model, its instructions, the channels that may start it, its tools and tool hooks, a budget and typed state.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// defined once at module scope: each call gets its run&#39;s context</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> lastReport = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Returns the date of the previous report.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (_input, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> context.state.get&lt;string&gt;(</span><span style="color:#E7C58C;">&#39;lastReport&#39;</span><span style="color:#E6DFDE;">)) </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;never&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> saveReport = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Remembers that a report was written now.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (_input, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        await</span><span style="color:#E6DFDE;"> context.state.set(</span><span style="color:#E7C58C;">&#39;lastReport&#39;</span><span style="color:#E6DFDE;">, context.run.trigger.receivedAt.toISOString());</span></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> { saved: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> };</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> reporter = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;weekly-report&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Summarize the open work items in the trigger payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [</span></span>
<span class="line"><span style="color:#E6DFDE;">        http.on(),</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron.on(</span><span style="color:#E7C58C;">&#39;0 8 * * 1&#39;</span><span style="color:#E6DFDE;">, { timezone: </span><span style="color:#E7C58C;">&#39;Europe/Berlin&#39;</span><span style="color:#E6DFDE;"> }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">    budget: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        maxSteps: </span><span style="color:#E7C58C;">10</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        maxTokens: </span><span style="color:#E7C58C;">50_000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        timeoutMs: </span><span style="color:#E7C58C;">5</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { lastReport, saveReport },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><h2 id="what-defineagent-checks" tabindex="-1">What <code>defineAgent()</code> checks <a class="header-anchor" href="#what-defineagent-checks" aria-label="Permalink to &quot;What \`defineAgent()\` checks&quot;">​</a></h2><p><code>defineAgent()</code> validates the definition and returns <code>{ name, definition }</code> with defaults applied. It throws <code>InvalidAgentDefinitionError</code> when:</p><ul><li>the name does not match <code>^[a-z0-9]+(-[a-z0-9]+)*$</code> (lowercase words joined by single hyphens), or is longer than 64 characters,</li><li>two subscriptions of the agent share an id,</li><li>a tool of a plain tool set declares the AI SDK&#39;s <code>needsApproval</code> (use <a href="/guide/approvals"><code>approve()</code></a> instead),</li><li>a <code>toolsContext</code> entry names a chamvi tool or no tool of a plain tool set (see <a href="/guide/tools#third-party-tools-with-their-own-context">Third-party tools with their own context</a>).</li></ul><p>The engine checks the rest when you construct it: agent names must be unique within one <code>Engine</code>, and every subscription must name a channel registered on the engine.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> agent = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;echo&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Repeat the payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">agent.name; </span><span style="color:#958A8B;">// &#39;echo&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">agent.definition.budget; </span><span style="color:#958A8B;">// { maxSteps: 20, timeoutMs: 900_000 }</span></span></code></pre></div><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>required</td><td>Unique per engine, lowercase words joined by <code>-</code>, at most 64 characters</td></tr><tr><td><code>model</code></td><td><code>ModelRef</code></td><td><code>EngineOptions.model</code></td><td>A <code>&#39;&lt;provider&gt;/&lt;model id&gt;&#39;</code> string resolved through <code>EngineOptions.models</code>, or any AI SDK <code>LanguageModel</code></td></tr><tr><td><code>instructions</code></td><td><code>string</code></td><td>required</td><td>System instructions</td></tr><tr><td><code>channels</code></td><td><code>ChannelSubscription[]</code></td><td>none</td><td>From <code>http.on()</code>, <code>webhook.on()</code>, <code>cron.on()</code>, <code>github.on()</code>. See <a href="/guide/channels">Channels</a></td></tr><tr><td><code>tools</code></td><td><code>ToolSet | (ctx) =&gt; ToolSet</code></td><td>none</td><td>A plain tool set, or a factory called for each execution. See <a href="#tools-and-their-context">Tools and their context</a></td></tr><tr><td><code>toolsContext</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>none</td><td>Per tool name, the context of a third-party tool. See <a href="/guide/tools#third-party-tools-with-their-own-context">Tools</a></td></tr><tr><td><code>toolPolicy</code></td><td><code>(toolName, { run }) =&gt; boolean</code></td><td>none</td><td>Tools the run may use, e.g. <code>requireToolPermission()</code>. See <a href="/guide/tools#restricting-tools-per-invoker">Restricting tools per invoker</a></td></tr><tr><td><code>state</code></td><td><code>Record&lt;string, StandardSchemaV1&gt;</code></td><td>none</td><td>Typed state collections. See <a href="/guide/state">Agent State</a></td></tr><tr><td><code>budget</code></td><td><code>Partial&lt;Budget&gt;</code></td><td><code>{ maxSteps: 20, timeoutMs: 900_000 }</code></td><td>See <a href="/guide/budgets">Budgets &amp; Timeouts</a></td></tr><tr><td><code>hooks</code></td><td><code>{ beforeToolExecution?, afterToolExecution? }</code></td><td>none</td><td>Run around every tool call: rewrite input or output, gate a tool with <code>approve()</code>. See <a href="/guide/approvals#gating-tools-you-did-not-write">Approvals &amp; Hooks</a></td></tr><tr><td><code>output</code></td><td><code>Output</code></td><td>none</td><td>AI SDK structured output, e.g. <code>Output.object({ schema })</code>. See <a href="#structured-output">Structured output</a></td></tr></tbody></table><p>The budget you pass is merged over the defaults, so <code>budget: { maxSteps: 5 }</code> keeps the 15 minute timeout.</p><h2 id="tools-and-their-context" tabindex="-1">Tools and their context <a class="header-anchor" href="#tools-and-their-context" aria-label="Permalink to &quot;Tools and their context&quot;">​</a></h2><p><code>tools</code> is usually a plain AI SDK <code>ToolSet</code>, defined once at module scope (see the example above). Tools built with <code>defineTool()</code> (or <a href="/guide/effect-tools"><code>defineEffectTool()</code></a>) get the run context as <code>context</code>, the second argument of <code>execute</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>state</code></td><td><code>AgentState</code></td><td>The agent&#39;s <a href="/guide/state">state</a></td></tr><tr><td><code>run.runId</code></td><td><code>string</code></td><td>Id of the run being executed</td></tr><tr><td><code>run.agent</code></td><td><code>string</code></td><td>Agent name</td></tr><tr><td><code>run.trigger</code></td><td><code>TriggerEnvelope</code></td><td>The envelope that started the run; <code>run.trigger.invoker</code> is who started it, if an authenticator knew</td></tr><tr><td><code>run.signal</code></td><td><code>AbortSignal</code></td><td>Aborts on cancel, drain, a lost lease or the run timeout, and once the execution has ended</td></tr><tr><td><code>artifacts</code></td><td><code>IRunArtifacts</code></td><td>The run&#39;s files: <code>put()</code>, <code>get(id)</code>, <code>list()</code>. See <a href="#files">Files</a></td></tr></tbody></table><p>The engine builds one <code>ToolContext</code> per execution and hands it, through the AI SDK&#39;s <code>toolsContext</code>, to every tool whose <code>contextSchema</code> is chamvi&#39;s <code>toolContextSchema</code>, which is what <code>defineTool()</code> sets. Other tools (a plain <code>tool()</code>, a third-party tool) get no chamvi context. Every call of an execution gets the same object: treat it as immutable. It holds <code>run</code>, <code>state</code>, <code>artifacts</code> and <code>channels</code>, the run-bound handles a tool sends through (see <a href="/guide/channels#outbound-from-tools">Outbound from tools</a>). Pass <code>context.run.signal</code> on to <code>fetch</code> and other cancellable work.</p><p>For typed state, name the schema: <code>defineTool&lt;Input, Output, typeof schema&gt;({ ... })</code> types <code>context.state</code> by the agent&#39;s collections. The agent does not check that schema against its own <code>state</code>: a tool typed for other collections still compiles, and at run time reads of an undeclared collection are empty and writes fail as tool errors.</p><p><code>tools</code> can also be a factory <code>(ctx) =&gt; ToolSet</code>, called once per execution with the same <code>ToolContext</code>. Use it for dynamic sets: tools from an MCP client, or descriptions built from async state (a tool&#39;s <code>description</code> function runs synchronously, so it cannot read the store itself).</p><p>The tools stay plain AI SDK tools. When the agent declares <code>state</code>, the engine adds generated state tools; your tools win on a name clash. Every <a href="/guide/effect-tools">effect tool</a> is then wrapped so it applies at most once per effect key.</p><h2 id="structured-output" tabindex="-1">Structured output <a class="header-anchor" href="#structured-output" aria-label="Permalink to &quot;Structured output&quot;">​</a></h2><p>By default a completed run&#39;s <code>output</code> is the text of the model&#39;s last answer. With <code>output</code>, an AI SDK <code>Output</code>, <code>output</code> is the parsed value instead:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> labeler = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;labeler&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Label the issue in the trigger payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [http.on()],</span></span>
<span class="line"><span style="color:#958A8B;">    // run.output is { label, reason } instead of the final text</span></span>
<span class="line"><span style="color:#E6DFDE;">    output: Output.object({</span></span>
<span class="line"><span style="color:#E6DFDE;">        schema: z.object({</span></span>
<span class="line"><span style="color:#E6DFDE;">            label: z.enum([</span><span style="color:#E7C58C;">&#39;bug&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;feature&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;question&#39;</span><span style="color:#E6DFDE;">]),</span></span>
<span class="line"><span style="color:#E6DFDE;">            reason: z.string(),</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The model may call tools first; only the final answer is parsed. A final answer that is no valid JSON or fails the schema fails the run with <code>ValidationError</code> (<code>run.error.code</code> <code>validation_error</code>, the message from the AI SDK&#39;s cause, its quoted text cut to 500 characters; the whole answer stays in the <code>llm</code> step). Two loop ends have no answer to parse and fail the run with <code>IncompleteResponseError</code> (<code>incomplete_response</code>) instead: an answer cut off at the output token limit (finish reason <code>length</code>), and a loop that ended on a tool call nothing executed (a tool without <code>execute</code>, outside a budget stop). A run whose step budget an earlier execution used up parses the last answer in its checkpoint the same way. An agent without <code>output</code> keeps completing with the text it got in both cases.</p><p>The <code>ToolLoopAgent</code> gets your <code>Output</code> with one change: its <code>parsePartialOutput</code> is not called while the answer streams (chamvi reads no partial output, and re-parsing the growing answer on every delta costs time). <code>run.delta</code> events arrive per model delta, as without <code>output</code>.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>A run can start with files (<a href="/guide/channels#attachments">attachments</a>) and tools can store files of their own. Both are artifacts of the run: metadata (<code>id</code>, <code>runId</code>, <code>agent</code>, <code>mediaType</code>, <code>filename?</code>, <code>size</code>, <code>createdAt</code>) plus the bytes, kept in the store&#39;s <code>IArtifactStore</code>. The <code>artifacts</code> of the tool context is scoped to the run: <code>put({ mediaType, filename?, data })</code> stores a <code>Uint8Array</code> and returns the <code>Artifact</code>, <code>get(id)</code> returns <code>{ artifact, data }</code> (or <code>undefined</code>, also for another run&#39;s artifact) and <code>list()</code> returns the run&#39;s artifacts by <code>createdAt</code> (attachments in the order they were given, ids <code>&lt;runId&gt;.0000</code>, ...; tool files get random UUIDs).</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// an effect tool: a recovered run does not store the chart twice</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> saveChart = defineEffectTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Renders the points as a PNG chart and stores it with the run.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ points: z.array(z.number()) }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ points }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> artifact = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> context.artifacts.put({</span></span>
<span class="line"><span style="color:#E6DFDE;">            mediaType: </span><span style="color:#E7C58C;">&#39;image/png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            filename: </span><span style="color:#E7C58C;">&#39;chart.png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            data: </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> renderChart(points),</span></span>
<span class="line"><span style="color:#E6DFDE;">        });</span></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> { artifactId: artifact.id };</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> charter = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;charter&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Chart the numbers in the attached CSV.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [http.on()],</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { saveChart },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>put()</code> is not an effect by itself: a recovered run repeats the step in progress, so call it inside a <a href="/guide/effect-tools"><code>defineEffectTool</code></a> to store a file exactly once. Over HTTP, <code>GET /runs/:id/artifacts</code> lists them and <code>GET /runs/:id/artifacts/:artifactId</code> downloads one (see <a href="/guide/http#files">HTTP API</a>).</p><h2 id="many-agents-per-engine" tabindex="-1">Many agents per engine <a class="header-anchor" href="#many-agents-per-engine" aria-label="Permalink to &quot;Many agents per engine&quot;">​</a></h2><p>One engine runs any number of agents. They share the store, the concurrency limit and the channels:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> triage = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Triage the issue.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> digest = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Summarize the day.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store: </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> MemoryStore(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [triage, digest],</span></span>
<span class="line"><span style="color:#958A8B;">    // tools reach it with ctx.channels.findOneOrFail(&#39;console&#39;)</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [consoleChannel()],</span></span>
<span class="line"><span style="color:#E6DFDE;">    maxConcurrentRuns: </span><span style="color:#E7C58C;">8</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    claimTtlMs: </span><span style="color:#E7C58C;">30_000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>dispatch()</code> names the agent per run. An agent the engine does not hold throws <code>AgentNotFoundError</code> (<code>agent_not_found</code>, 404 over HTTP).</p><p>The set can change while the engine runs: <code>engine.putAgent(agent)</code> adds an agent or replaces the one of the same name, <code>engine.removeAgent(name)</code> removes it, and both emit <code>agents.changed</code> (<code>{ name, kind: &#39;added&#39; | &#39;replaced&#39; | &#39;removed&#39; }</code>), which the cron channel and <code>@chamvi/http</code> follow. Replacing or removing an agent first cancels its unsettled runs. An app loads such agents from a folder: see <a href="/guide/agent-folders">Agent Folders</a>.</p>`,32)])])}const E=s(o,[["render",l]]);export{u as __pageData,E as default};
